<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Scopes\Infrastructure\Service;

use Civi\Lughauth\Shared\Value\Random;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientRef;
use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\UserConsentedScopes;
use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\UserConsentedScopesAttributes;
use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\Gateway\UserConsentedScopesFilter;
use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\Gateway\UserConsentedScopesWriteGateway;

final class UserConsentedScopeGrant
{
    public function __construct(
        private readonly UserConsentedScopesWriteGateway $write,
    ) {
    }

    /**
     * Grants the given scopes for a user+client pair.
     * Idempotent: already-granted scopes are skipped; revoked scopes are re-granted.
     *
     * @param string[] $scopes
     */
    public function grant(UserRef $user, TrustedClientRef $client, array $scopes): void
    {
        if (!$scopes) {
            return;
        }

        $filter = (new UserConsentedScopesFilter())
            ->withUser($user)
            ->withTrustedClient($client);

        $existing = [];
        foreach ($this->write->listForUpdate($filter)->values() as $consent) {
            $scope = $consent->getScope();
            if (null !== $scope) {
                $existing[$scope] = $consent;
            }
        }

        $now = new \DateTimeImmutable();

        foreach ($scopes as $scope) {
            if (isset($existing[$scope])) {
                $consent = $existing[$scope];
                if (!$consent->isGranted()) {
                    $updated = $consent->update(
                        (new UserConsentedScopesAttributes())
                            ->granted(true)
                            ->decisionAt($now)
                    );
                    $this->write->update($consent, $updated);
                }
            } else {
                $newConsent = UserConsentedScopes::create(
                    (new UserConsentedScopesAttributes())
                        ->uid(Random::uuid())
                        ->user($user)
                        ->trustedClient($client)
                        ->scope($scope)
                        ->granted(true)
                        ->decisionAt($now)
                );
                $this->write->create($newConsent);
            }
        }
    }
}
